import json,re,html,hashlib
R=Path(__file__).resolve().parents[2];A=json.loads((R/'scripts/project-sources/piazzetta-chaos-assets.json').read_text());e=html.escape
css='''
.pc-main{max-width:1600px;margin:auto;padding:0 4vw}.pc-intro{padding:55px 0 60px;border-bottom:1px solid #bcb9b3}.pc-eyebrow,.pc-label,.pc-meta,.pc-figure figcaption,.pc-link{font:11px/1.6 "IBM Plex Mono",monospace;text-transform:uppercase}.pc-eyebrow{display:flex;justify-content:space-between;gap:20px}.pc-intro h1{font-size:clamp(62px,10.5vw,170px);line-height:.86;letter-spacing:-.065em;margin:48px 0}.pc-lead{display:grid;grid-template-columns:1.6fr 1fr;gap:9vw}.pc-lead>p{font-size:clamp(22px,2.4vw,38px);line-height:1.16;max-width:820px;margin:0}.pc-meta{display:grid;gap:15px}.pc-meta dt{opacity:.55}.pc-meta dd{margin:0}.pc-section{padding:65px 0;border-bottom:1px solid #bcb9b3}.pc-section h2{font-size:clamp(36px,5vw,78px);line-height:.98;letter-spacing:-.045em;margin:20px 0 28px;max-width:1000px}.pc-text{font-size:19px;line-height:1.5;max-width:780px;margin:0 0 34px}.pc-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;align-items:start}.pc-grid.four{grid-template-columns:repeat(4,minmax(0,1fr))}.pc-grid.hero-pair{grid-template-columns:1fr 1.35fr;align-items:center}.pc-figure{margin:0;min-width:0}.pc-figure img{display:block;width:100%;height:auto}.pc-figure figcaption{margin:12px 0 8px;opacity:.7;font-size:10px}.pc-portrait-pair .pc-figure img,.pc-portrait-pair .pc-figure video{aspect-ratio:9/16;width:100%;height:auto;max-height:none;object-fit:contain}.pc-figure video{display:block;width:100%;height:auto;max-height:75vh;background:#111;object-fit:contain}.pc-feature{margin-top:28px}.pc-dark{background:#151513;color:#ece9e3;margin:0 -4vw;padding:65px 4vw}.pc-dark .pc-label{color:#b0ff00}.pc-link{display:inline-flex;align-items:center;gap:24px;border-bottom:1px solid currentColor;padding:15px 0;margin-top:22px;text-decoration:none}.pc-link:hover{color:#a6532a}.pc-link:focus-visible{outline:2px solid #a6532a;outline-offset:8px}.pc-next{padding:60px 0}.pc-next a{font-size:clamp(30px,4vw,66px);line-height:1.1;letter-spacing:-.035em;display:block;margin-top:20px}.pc-operations{list-style:none;margin:24px 0 35px;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.pc-operations li{border-top:1px solid #777;padding:18px 0;font-size:17px;line-height:1.4}.pc-operations b{display:block;font:11px/1.5 "IBM Plex Mono",monospace;margin-bottom:12px}.pc-note{font:11px/1.6 "IBM Plex Mono",monospace;max-width:750px;opacity:.7}.pc-strip{margin-top:30px;overflow:hidden}.pc-strip img{width:100%;height:auto;display:block}@media(max-width:700px){.pc-intro{padding-top:35px}.pc-eyebrow{font-size:9px}.pc-intro h1{margin:36px 0}.pc-lead{grid-template-columns:1fr;gap:28px}.pc-meta{grid-template-columns:1fr 1fr}.pc-grid.hero-pair{grid-template-columns:1fr}.pc-grid.four{grid-template-columns:repeat(2,minmax(0,1fr))}.pc-grid{gap:14px}.pc-operations{grid-template-columns:1fr}.pc-section,.pc-dark{padding-top:42px;padding-bottom:42px}.pc-text{font-size:17px}.pc-grid.stack{grid-template-columns:1fr}}
'''
