 def section(n,heading,text,media,dark=False):return f'<section class="pc-section'+(' pc-dark' if dark else '')+f'"><span class="pc-label">{n}</span><h2>{heading}</h2><p class="pc-text">{text}</p>{media}</section>'
 def grid(*items,cls=''):return '<div class="pc-grid '+cls+'">'+''.join(items)+'</div>'
