  body+=section('02 / EVENT MANAGEMENT',T('LA MIA PARTE,<br>DALL’INIZIO ALLA SERATA.','MY ROLE,<br>FROM PLANNING TO THE NIGHT.'),T('Per il party ho seguito PR, gestione ticket, pubblicazioni, allestimento e materiali fisici. La comunicazione e l’organizzazione sono state sviluppate insieme.','For the party I handled PR, ticket management, publishing, setup and physical materials. Communication and event organisation were developed together.'),'<ul class="pc-operations">'+''.join(f'<li><b>{a}</b>{b}</li>' for a,b in ops)+'</ul>'+grid(fig('invitation',T('Invito originale Chaos as Duality con istruzioni di registrazione','Original Chaos as Duality invitation with registration instructions'),T('Documento storico / invito, non un modulo attivo','Archive document / invitation, not an active form')),fig('chaos-preparty','Chaos as Duality — Bar La Piazzetta pre-party')),True)
  body+=section('03 / PRE-PARTY',T('LA SERATA INIZIA<br>ALLA PIAZZETTA.','THE NIGHT BEGINS<br>AT LA PIAZZETTA.'),T('Ho curato il pre-party al Bar La Piazzetta, dalla scelta dei drink all’identità e alle pubblicazioni. Underdog, Blizzard, Awareness e Overturn compongono il menu dedicato; la grafica anticipa il linguaggio del party.','I handled the pre-party at Bar La Piazzetta, from drink selection to identity and publications. Underdog, Blizzard, Awareness and Overturn form the dedicated menu; its graphics introduce the visual language of the party.'),grid(fig('chaos-drinks','Chaos as Duality — original pre-party drinks menu'),vid('preparty-film',T('Video originale / pre-party La Piazzetta','Original video / La Piazzetta pre-party')),cls='pc-portrait-pair')+f'<a class="pc-link" href="{prefix}/work/bar-la-piazzetta/">'+T('Il progetto Bar La Piazzetta →','The Bar La Piazzetta project →')+'</a>')
